		#endregion

		#region Add Find Destination Location MenuItem

		void AddFindDestinationLocationContextMenuItem()
		{
			if (!LinesGrid.ContextMenu.MenuItems.ContainsKey(Res.GetString("76ae37c5-7c07-4fc3-ab5c-bf47aca746b5", "Find Destination Location")))
			{
				var item = new ZMenuItem(ResString.GetMultilingualString("4a45117a-8502-419c-9937-1d0fb5ef2dd6", "Find Destination Location"), FindDestinationLocationMenuItemClick, Shortcut.CtrlL);
				LinesGrid.ContextMenu.MenuItems.Add(item);
				item.Name = "Find Destination Location";

				LinesGrid.ContextMenu.Popup += (sender, e) =>
					{
						var enabled = false;
						var docketLine = (WhsTransferLine)LinesGrid.SelectedElements.FirstOrDefault();
						if (docketLine != null)
						{
							enabled = !docketLine.LocationStringInfo.ReadOnly;
						}

						item.Enabled = enabled;
					};
			}
		}

		#endregion

		#region Assign Selected Lines to User Context MenuItems

		void AddAssignSelectedLinesToUserContextMenuItems()
		{
			var assignSelectedLinesToUserPickOnlyMenuItem = new ZMenuItem(
				ResString.GetMultilingualString("b56d0418-fe26-4c52-a414-9a5584de0632", "Pick Only"),
				delegate
				{ AssignLines(AssignLineOptions.PickOnly); });
			var assignSelectedLinesToUser = new ZMenuItem(ResString.GetMultilingualString("837d386c-fbc1-4d16-9a8e-4201537aff31", "Assign selected lines to User"), new MenuItem[] { assignSelectedLinesToUserPickOnlyMenuItem });

			var unassignSelectedLinesPickOnlyMenuItem = new ZMenuItem(
				ResString.GetMultilingualString("ed393219-4748-44aa-8235-7e8a61d427f3", "Pick Only"),
				delegate
				{ UnassignLines(); });
			var unassignSelectedLines = new ZMenuItem(ResString.GetMultilingualString("23fe29b9-db0f-44b9-aa9f-762294b258ed", "Un-assign selected lines"), new MenuItem[] { unassignSelectedLinesPickOnlyMenuItem });

			LinesGrid.ContextMenu.Popup += delegate
			{
				var selectedLines = LinesGrid.SelectedElements;

				assignSelectedLinesToUser.Enabled = !Docket.IsFinalisedOrCancelled && selectedLines.Cast<WhsTransferLine>().Any(l => !l.IsFinalised);
				EnableContextMenuItem(assignSelectedLinesToUserPickOnlyMenuItem, LinesGrid.SelectedElements, AssignLineOptions.PickOnly);

				unassignSelectedLines.Enabled = !Docket.IsFinalisedOrCancelled && selectedLines.Cast<WhsTransferLine>().Any(l => !l.IsFinalised);
				EnableContextMenuItem(unassignSelectedLinesPickOnlyMenuItem, LinesGrid.SelectedElements, AssignLineOptions.PickOnly);
			};

			LinesGrid.ContextMenu.MenuItems.Add(assignSelectedLinesToUser);
			LinesGrid.ContextMenu.MenuItems.Add(unassignSelectedLines);
		}

		void AssignLines(AssignLineOptions option)
		{
			var selectedElements = LinesGrid.SelectedElements;
			using (new DocketNotificationSubscriberWithWaitCursor(Docket, GetNotificationBuffer()))
			{
				var transfer = ((WhsTransfer)Docket);
				transfer.Option = option;

				var attacher = new AssignLinesToUserAttacher<WhsTransferLine>(selectedElements.Cast<WhsTransferLine>(), transfer.Factory);
				attacher.Show((IZForm)this.FindForm());
#if DEBUG
				LastShownTransferLineAttachPopupForTesting = attacher.LastShownAttachPopupForTesting;
				TransferLineAttacherForTesting = attacher;
#endif
			}
		}

		void UnassignLines()
		{
			var lines = LinesGrid.SelectedElements.Cast<ILineStaffAssigner>();
			foreach (var line in lines.Where(l => l.CanAssignOrUnAssignLine()))
			{
				line.UnAssignLine(null);
			}
		}

		void EnableContextMenuItem(ZMenuItem menu, BusinessObject[] selectedElements, AssignLineOptions option)
		{
			var transfer = ((WhsTransfer)Docket);
			transfer.Option = option;
			menu.Enabled = selectedElements.Cast<ILineStaffAssigner>().Any(l => l.CanAssignOrUnAssignLine());
		}

