		#region AddFinaliseLinesContextMenuItem

		void AddFinaliseLinesContextMenuItem()
		{
			var item = new ZMenuItem(ResString.GetMultilingualString("93f956d0-f3ff-498f-826c-49c375e12bec", "Finalize Line(s)"), FinaliseLinesMenuItemClick, Shortcut.CtrlF);
			LinesGrid.ContextMenu.MenuItems.Add(item);
			LinesGrid.ContextMenu.Popup += delegate
			{
				var docket = (WhsTransfer)Docket;
				item.Enabled = !docket.IsFinalisedOrCancelled && docket.IsMasterTransfer && !docket.IsTransferringForOrder;
			};
		}

		void FinaliseLinesMenuItemClick(object sender, EventArgs e)
		{
			var transfer = (WhsTransfer)Docket;
			var linesToFinalise = (LinesGrid.SelectedElements.Length > 0) ? LinesGrid.SelectedElements : transfer.Lines.ToArray();
			using (new DocketNotificationSubscriberWithWaitCursor(Docket, GetNotificationBuffer()))
			{
				transfer.ValidateAndFinaliseDocketLines(linesToFinalise.Cast<WhsTransferLine>(), true);
			}
		}

		#endregion

		#endregion

		#endregion

		#region Overrides

		protected override void OnDocketSubTypeChangedCore()
		{
			base.OnDocketSubTypeChangedCore();

			var isSrcTransfer = (Docket.WD_DocketSubType == TransferType.Codes.InterWhsSource);
			var isDestTransfer = (Docket.WD_DocketSubType == TransferType.Codes.InterWhsDest);

			if (LinesGrid.Columns.Count == 0)
			{
				LinesGrid.AfterBind += LinesGrid_AfterBind;
			}
			else
			{
				LinesGrid.AfterBind -= LinesGrid_AfterBind;

				if (LinesGrid.Columns["TransferFromWarehousePK"] != null)
				{
					LinesGrid.SetColumnVisible(isDestTransfer, "TransferFromWarehousePK");
					LinesGrid.Columns["TransferFromWarehousePK"].IsUnavailable = !isDestTransfer;
					LinesGrid.Columns["TransferFromWarehousePK"].ErrorMessageWhenUnavailable =
						LinesGrid.Columns["TransferFromWarehousePK"].ToString() + " " + Res.GetString("DCC86FEF-B8B6-4A3D-80BB-17EC7B394B0C", "column is only available for Inter-Warehouse Destination Transfers");
				}

				if (LinesGrid.Columns["DestinationWarehousePK"] != null)
				{
					LinesGrid.SetColumnVisible(isSrcTransfer, "DestinationWarehousePK");
					LinesGrid.Columns["DestinationWarehousePK"].IsUnavailable = !isSrcTransfer;
					LinesGrid.Columns["DestinationWarehousePK"].ErrorMessageWhenUnavailable =
						LinesGrid.Columns["DestinationWarehousePK"].ToString() + " " + Res.GetString("8403cb1d-ec05-450d-a391-c8dd73b8074d", "column is only available for Inter-Warehouse Source Transfers");
				}
			}
		}

		void LinesGrid_AfterBind(object sender, EventArgs e)
		{
			OnDocketSubTypeChanged(sender, e);
		}

		#endregion

		#region Events

		void FindDestinationLocationMenuItemClick(object sender, EventArgs e)
		{
			FindDestinationLocationCore();
		}

		protected void FindDestinationLocationCore()
		{
			if (LinesGrid.ListManager != null && LinesGrid.ListManager.Position >= 0)
			{
				WhsDocketLine docketLine = (WhsDocketLine)LinesGrid.ListManager.GetCurrent();
				if (docketLine != null)
				{
					ChooseInventoryRecordForDestinationLocation(docketLine);
				}
			}
			else
			{
				Enterprise.ZArchitecture.Environment.Globals.Message.ShowError(Res.GetString("63b02982-90c6-4da3-ba94-6096089c55a4", "Please enter a new row (by entering a value into any column) before using the Find Attributes option"));
			}
		}

		void ChooseInventoryRecordForDestinationLocation(WhsDocketLine docketLine)
		{
			var inventoryCollection = new WhsInventoryViewCollection(Docket.Factory);

			inventoryCollection.AddWarehouseClientProductFilterDefaults(Docket.WD_WW_Whs, Docket.WD_OH_Client, docketLine.WE_OP);
			inventoryCollection.AddAttributeFilterDefaults(docketLine);

			var recordChooser = new ZRecordChooser<WhsInventoryView>(Enterprise.ZArchitecture.Modules.ModuleIDs.WhsInventory, inventoryCollection);
			recordChooser.ShowModal(LinesGrid.FindForm(), delegate(WhsInventoryView[] selectedInventory)
			{
				if (selectedInventory.Length > 0 && docketLine.CanUpdateFromInventory)
				{
					UseChoosenInventoryRowForDestinationLocation(docketLine, selectedInventory[0]);
				}
			});
		}

		protected virtual void UseChoosenInventoryRowForDestinationLocation(WhsDocketLine docketLine, WhsInventoryView inventory)
		{
			docketLine.WE_WL = inventory.WI_WL;
		}

		#endregion
	}
